const crypto = require('crypto');

const secret = $env.LENDLOOP_WEBHOOK_SECRET;
if (!secret) {
  throw new Error('LENDLOOP_WEBHOOK_SECRET is not set on the n8n instance');
}

const item = $input.first();
const headers = item.json.headers || {};
const headerMap = {};
for (const [key, value] of Object.entries(headers)) {
  headerMap[String(key).toLowerCase()] = Array.isArray(value) ? value[0] : value;
}

const timestamp = headerMap['x-lendloop-timestamp'] || '';
const signature = headerMap['x-lendloop-signature'] || '';
const match = /^v1=([0-9a-f]{64})$/i.exec(String(signature));

let raw = '';
if (item.binary && item.binary.data && item.binary.data.data) {
  raw = Buffer.from(item.binary.data.data, 'base64').toString('utf8');
} else if (typeof item.json.body === 'string') {
  raw = item.json.body;
} else if (item.json.body && typeof item.json.body === 'object') {
  raw = JSON.stringify(item.json.body);
} else {
  const copy = { ...item.json };
  delete copy.headers;
  delete copy.params;
  delete copy.query;
  raw = JSON.stringify(copy.body !== undefined ? copy.body : copy);
}

const now = Math.floor(Date.now() / 1000);
const ts = Number(timestamp);
const validTime = Number.isFinite(ts) && Math.abs(now - ts) <= 300;
const expected = crypto.createHmac('sha256', secret).update(`${timestamp}.${raw}`).digest('hex');
const provided = match ? match[1].toLowerCase() : '';

let ok = false;
if (validTime && provided.length === expected.length && provided.length > 0) {
  ok = crypto.timingSafeEqual(Buffer.from(provided, 'utf8'), Buffer.from(expected, 'utf8'));
}

if (!ok) {
  return [{ json: { ok: false, reason: validTime ? 'signature_mismatch' : 'invalid_timestamp' } }];
}

const event = JSON.parse(raw);
return [{
  json: {
    ok: true,
    event: event.event,
    eventId: event.eventId,
    requestId: event.requestId,
    status: event.status,
    startDate: event.startDate,
    endDate: event.endDate,
    toolName: event.toolName,
    notify: event.notify,
  },
}];

const event = $input.first().json;
const who = event.notify || {};
const destination = who.email || who.name || 'unknown neighbor';
const message = event.status === 'pending'
  ? `New borrow request for "${event.toolName}" (${event.startDate}–${event.endDate}).`
  : `Borrow request for "${event.toolName}" is now ${event.status}.`;

// Logged mock notification, as allowed by the assignment.
// Swap this node for Email, Slack, or Discord and keep the same fields.
const record = {
  channel: 'log',
  to: destination,
  reason: who.reason || 'status_update',
  requestId: event.requestId,
  status: event.status,
  message,
  at: new Date().toISOString(),
};
console.log('[LendLoop] request notification', record);
return [{ json: { ok: true, notification: record } }];
